import { useCallback, useEffect, useRef, type ReactNode } from "react";
import { Link, useNavigate } from "react-router";
import {
  copy,
  resistanceStepCopy,
  stepCopy,
  type ResistanceStepSlug,
  type StepSlug,
} from "../copy/en";
import { PageBody, PageFrame } from "./PageFrame";
import styles from "./Shell.module.css";
import { neighbourResistanceStep, neighbourStep, resistanceStepPath, stepPath } from "./steps";
import { useStepKeys } from "./useStepKeys";

/** One step in the navigation: `path` is undefined while the step has no page to go to. */
interface StepLink {
  slug: string;
  title: string;
  path: string | undefined;
  current: boolean;
}

interface StepShellProps {
  /** The current step's slug. Only the sideways scroll reads it; the links carry the rest. */
  step: string;
  title: string;
  intro: string;
  links: readonly StepLink[];
  previousPath: string | undefined;
  nextPath: string | undefined;
  /** What the flow is about (a Disease, a pathogen), shown once in the header. */
  subject?: string | undefined;
  /** `document`: the page grows with its content and the window scrolls. Default: fit the window. */
  flow?: "fit" | "document";
  children: ReactNode;
}

/**
 * The app shell: product, subject and step navigation in the header; then the step title, its
 * intro and the figure; then Back and Next at the bottom right, where a reader finishes the step.
 * The step's name is said once, as the page title; the navigation marks the current step by
 * state (underline and aria-current) and the buttons never repeat a step name.
 *
 * It knows nothing about which flow it is drawing: `Shell` and `ResistanceShell` below work out
 * the steps and their addresses, so both flows get one piece of chrome and one set of keys.
 */
function StepShell({
  step,
  title,
  intro,
  links,
  previousPath,
  nextPath,
  subject,
  flow,
  children,
}: StepShellProps) {
  const navigate = useNavigate();

  const goPrevious = useCallback(() => {
    if (previousPath !== undefined) void navigate(previousPath);
  }, [navigate, previousPath]);
  const goNext = useCallback(() => {
    if (nextPath !== undefined) void navigate(nextPath);
  }, [navigate, nextPath]);
  useStepKeys(goPrevious, goNext);

  // On narrow screens the steps scroll sideways; keep the current one in view.
  const currentLink = useRef<HTMLAnchorElement>(null);
  useEffect(() => {
    const link = currentLink.current;
    const nav = link?.closest("nav");
    if (!link || !nav || nav.scrollWidth <= nav.clientWidth) return;
    const linkBox = link.getBoundingClientRect();
    const navBox = nav.getBoundingClientRect();
    nav.scrollLeft += linkBox.left + linkBox.width / 2 - (navBox.left + navBox.width / 2);
  }, [step]);

  return (
    <PageFrame
      flow={flow}
      header={
        <>
          {subject !== undefined && (
            <span className={styles.subject} title={subject}>
              <span className={styles.subjectMark} aria-hidden="true" />
              <span className={styles.subjectName}>{subject}</span>
            </span>
          )}
          <nav className={styles.nav} aria-label={copy.stepsLabel}>
            <ol className={styles.navList}>
              {links.map((item) => (
                <li key={item.slug} className={styles.navItem}>
                  {item.path === undefined ? (
                    <span className={styles.navLink} aria-disabled="true">
                      {item.title}
                    </span>
                  ) : (
                    <Link
                      to={item.path}
                      className={styles.navLink}
                      ref={item.current ? currentLink : undefined}
                      aria-current={item.current ? "step" : undefined}
                    >
                      {item.title}
                    </Link>
                  )}
                </li>
              ))}
            </ol>
          </nav>
        </>
      }
      footer={
        <div className={styles.actions}>
          <button
            type="button"
            className={styles.button}
            onClick={goPrevious}
            disabled={previousPath === undefined}
          >
            {copy.back}
          </button>
          <button
            type="button"
            className={`${styles.button ?? ""} ${styles.primary ?? ""}`}
            onClick={goNext}
            disabled={nextPath === undefined}
          >
            {copy.next}
          </button>
        </div>
      }
    >
      <PageBody title={title} intro={intro}>
        {children}
      </PageBody>
    </PageFrame>
  );
}

interface ShellProps {
  step: StepSlug;
  /** Absent on the landing page, before a Disease has been chosen. */
  experimentId?: string | undefined;
  /** The Experiment's Disease, shown once in the header. */
  disease?: string | undefined;
  /** The step's figure. */
  children: ReactNode;
}

/** The shell of the gated disease flow (`src/app/flags.ts`): the eight Experiment steps. */
export function Shell({ step, experimentId, disease, children }: ShellProps) {
  const { title, intro } = stepCopy(step);
  const previous = neighbourStep(step, -1);
  const next = neighbourStep(step, 1);
  return (
    <StepShell
      step={step}
      title={title}
      intro={intro}
      links={copy.steps.map((item) => ({
        slug: item.slug,
        title: item.title,
        path: stepPath(experimentId, item.slug),
        current: item.slug === step,
      }))}
      previousPath={previous && stepPath(experimentId, previous)}
      nextPath={next && stepPath(experimentId, next)}
      subject={disease}
    >
      {children}
    </StepShell>
  );
}

interface ResistanceShellProps {
  step: ResistanceStepSlug;
  /** Absent on `/resistance`, before a resistance profile has been built. */
  profileId?: string | undefined;
  /** The profile's pathogen, shown once in the header. */
  pathogen?: string | undefined;
  /** The step's figure. */
  children: ReactNode;
}

/** The shell of the antibiotic resistance flow: the pathogen input, then the resistance map. */
export function ResistanceShell({ step, profileId, pathogen, children }: ResistanceShellProps) {
  const { title, intro } = resistanceStepCopy(step);
  const previous = neighbourResistanceStep(step, -1);
  const next = neighbourResistanceStep(step, 1);
  return (
    <StepShell
      step={step}
      title={title}
      intro={intro}
      links={copy.resistanceSteps.map((item) => ({
        slug: item.slug,
        title: item.title,
        path: resistanceStepPath(profileId, item.slug),
        current: item.slug === step,
      }))}
      previousPath={previous && resistanceStepPath(profileId, previous)}
      nextPath={next && resistanceStepPath(profileId, next)}
      subject={pathogen}
      // These steps are read down the page, so the window scrolls and nothing is boxed in a
      // scroll area; Back and Next follow the content.
      flow="document"
    >
      {children}
    </StepShell>
  );
}
import {
  resistanceStepIndex,
  resistanceStepSlugs,
  stepIndex,
  stepSlugs,
  type ResistanceStepSlug,
  type StepSlug,
} from "../copy/en";

/** Step 1 before any Experiment exists: the disease search that the introduction leads to. */
export const EXPLORE_PATH = "/explore";

/** Where a step lives. Without an Experiment only step 1 has a page: the disease search. */
export function stepPath(experimentId: string | undefined, slug: StepSlug): string | undefined {
  if (experimentId === undefined) return slug === "disease" ? EXPLORE_PATH : undefined;
  return `/e/${encodeURIComponent(experimentId)}/${slug}`;
}

/** The step `offset` places away from `slug`, or undefined past either end. */
export function neighbourStep(slug: StepSlug, offset: -1 | 1): StepSlug | undefined {
  return stepSlugs[stepIndex(slug) + offset];
}

/** Step 1 of the resistance flow, before a profile has been built: the pathogen input. */
export const RESISTANCE_PATH = "/resistance";

/**
 * Where a resistance step lives. Without a profile only step 1 has a page, as in the disease
 * flow: nothing can be mapped before an isolate's determinants are known.
 */
export function resistanceStepPath(
  profileId: string | undefined,
  slug: ResistanceStepSlug,
): string | undefined {
  if (profileId === undefined) return slug === "pathogen" ? RESISTANCE_PATH : undefined;
  return `${RESISTANCE_PATH}/${encodeURIComponent(profileId)}/${slug}`;
}

/** The resistance step `offset` places away from `slug`, or undefined past either end. */
export function neighbourResistanceStep(
  slug: ResistanceStepSlug,
  offset: -1 | 1,
): ResistanceStepSlug | undefined {
  return resistanceStepSlugs[resistanceStepIndex(slug) + offset];
}
/* Header, after the product name: what the flow is about, and the steps. Footer: Back and Next. */

/* A long name gives way to the steps: it ends in an ellipsis rather than push them out. */
.subject {
  display: inline-flex;
  flex: 0 1 auto;
  align-items: center;
  min-width: 0;
  gap: var(--space-8);
  font-size: var(--text-body-sm);
  color: var(--color-grey-1);
  white-space: nowrap;
}

.subjectName {
  overflow: hidden;
  text-overflow: ellipsis;
}

.subjectMark {
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-disease);
}

.nav {
  flex: none;
  align-self: stretch;
  margin-left: auto;
}

.navList {
  display: flex;
  gap: var(--space-16);
  height: 100%;
}

.navItem {
  display: flex;
}

.navLink {
  position: relative;
  display: flex;
  align-items: center;
  font-size: var(--text-body-sm);
  font-stretch: 92%;
  color: var(--color-grey-2);
  white-space: nowrap;
  text-decoration: none;
  transition: color var(--duration-quick);
}

.navLink::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 2px;
  background: var(--color-ink);
  transform: scaleX(0);
  transition: transform var(--duration-quick) var(--ease-out);
  content: "";
}

a.navLink:hover,
.navLink[aria-current="step"] {
  color: var(--color-ink);
}

.navLink[aria-current="step"]::after {
  transform: scaleX(1);
}

.navLink:focus-visible {
  outline: none;
}

/* The link fills the header's height, so its focus ring hugs the label instead. */
.navLink:focus-visible::before {
  position: absolute;
  inset: 14px calc(-1 * var(--space-8));
  border: 2px solid var(--color-ink);
  border-radius: var(--radius-control);
  content: "";
}

.navLink[aria-disabled="true"] {
  cursor: default;
}

.actions {
  display: flex;
  flex: none;
  gap: var(--space-8);
}

.button {
  display: inline-flex;
  align-items: center;
  height: var(--control-height);
  padding: 0 var(--space-16);
  border: 1px solid var(--color-ink);
  border-radius: var(--radius-control);
  background: var(--color-paper);
  font-size: var(--text-body-sm);
  font-weight: var(--weight-medium);
  white-space: nowrap;
}

.button:hover {
  background: var(--color-hover);
}

.primary {
  background: var(--color-ink);
  color: var(--color-paper);
}

.primary:hover {
  background: var(--color-ink-hover);
}

.button:disabled {
  opacity: 0.3;
  cursor: default;
  pointer-events: none;
}

@media (max-width: 1360px) {
  .subject {
    font-size: var(--text-label);
  }

  .navList {
    gap: var(--space-12);
  }

  .navLink {
    font-size: var(--text-label);
    font-stretch: 88%;
  }

  .button {
    padding: 0 var(--space-12);
  }
}

@media (min-width: 1700px) {
  .navList {
    gap: 28px;
  }
}

/* Narrow screens: the steps move to their own scrolling row under the product. */
@media (max-width: 1100px) {
  .nav {
    order: 3;
    flex-basis: calc(100% + 2 * var(--page-gutter));
    height: 48px;
    margin: 0 calc(-1 * var(--page-gutter));
    padding: 0 var(--page-gutter);
    overflow-x: auto;
    border-top: 1px solid var(--color-rule);
  }
}

import { Navigate, type RouteObject } from "react-router";
import { diseaseFlowEnabled } from "./flags";
import { EvaluationPage } from "./routes/EvaluationPage";
import { ExperimentLayout } from "./routes/ExperimentLayout";
import { ExplorePage } from "./routes/ExplorePage";
import { IntroPage } from "./routes/IntroPage";
import { NotFoundPage } from "./routes/NotFoundPage";
import { PathogenPage } from "./routes/PathogenPage";
import { ResistanceLayout } from "./routes/ResistanceLayout";
import { ResistanceStep } from "./routes/ResistanceStep";
import { RouteErrorPage } from "./routes/RouteErrorPage";
import { StepFigure } from "./routes/StepFigure";
import { EXPLORE_PATH, RESISTANCE_PATH } from "./steps";

/**
 * The COVID-19 disease flow of plan.md: the disease search, an Experiment's eight steps and the
 * ranking evaluation. Mounted only while `diseaseFlowEnabled` (issue #32), so by default these
 * addresses are not found and the app has one flow, the antibiotic one.
 */
const diseaseFlowRoutes: RouteObject[] = [
  { path: EXPLORE_PATH, element: <ExplorePage /> },
  {
    // The layout loads the Experiment and holds the persistent network; the step adds panels.
    path: "e/:experimentId",
    element: <ExperimentLayout />,
    children: [{ path: ":step", element: <StepFigure /> }],
  },
  { path: "evaluation", element: <EvaluationPage /> },
];

/**
 * The antibiotic resistance flow. Always mounted, including while the disease flow is on, so the
 * two can be worked on and tested side by side; only the address of `/` depends on the flag.
 */
const resistanceFlowRoutes: RouteObject[] = [
  { path: RESISTANCE_PATH, element: <PathogenPage /> },
  {
    // The layout loads the profile and its candidates; the step adds panels.
    path: `${RESISTANCE_PATH}/:profileId`,
    element: <ResistanceLayout />,
    children: [{ path: ":step", element: <ResistanceStep /> }],
  },
];

/** Every address the app answers, with the disease flow's own mounted only when `diseaseFlow`. */
export function createRoutes(diseaseFlow: boolean): RouteObject[] {
  return [
    {
      errorElement: <RouteErrorPage />,
      children: [
        {
          index: true,
